import{_ as l}from"./chunks/image8.DoghIq9q.js";import{_ as A,o as c,c as g,ah as h}from"./chunks/framework.5RDmLyoT.js";const d="/projects/Qtruck/en/latest/assets/image2.B9UxWkid.png",p="/projects/Qtruck/en/latest/assets/image3.OfudpXHI.png",m="/projects/Qtruck/en/latest/assets/image4.w5Yhu7Oy.png",b="data:image/png;base64,",u="data:image/png;base64,",w="/projects/Qtruck/en/latest/assets/image7.Ci4jOZtE.png",f="data:image/png;base64,",k="/projects/Qtruck/en/latest/assets/image9.Cwb_TeTZ.png",x="/projects/Qtruck/en/latest/assets/image10.2TPPooOm.png",R="/projects/Qtruck/en/latest/assets/image2.GXYJbknK.png",I="/projects/Qtruck/en/latest/assets/image3.jEHSGLYX.png",S="/projects/Qtruck/en/latest/assets/image4.DfjfVVAX.png",E="data:image/png;base64,",i="data:image/png;base64,",C="data:image/png;base64,",v="/projects/Qtruck/en/latest/assets/image8.uldPe0WH.png",y="/projects/Qtruck/en/latest/assets/image9.D29mwvil.png",q="/projects/Qtruck/en/latest/assets/image2.BWFT7aCu.png",e="/projects/Qtruck/en/latest/assets/image3.DFRs6lH1.jpg",G="/projects/Qtruck/en/latest/assets/image4.CFqrHWru.png",r="data:image/png;base64,",B="data:image/png;base64,",a="data:image/png;base64,",P="/projects/Qtruck/en/latest/assets/image9.gD3LcXkt.png",F="/projects/Qtruck/en/latest/assets/image10.CZOkFQez.png",n="/projects/Qtruck/en/latest/assets/image2.DnlehptA.png",U="/projects/Qtruck/en/latest/assets/image3.CUbw8MNT.png",j="data:image/png;base64,",O="data:image/png;base64,",z="data:image/png;base64,",Q="data:image/png;base64,",D="data:image/png;base64,",Y="/projects/Qtruck/en/latest/assets/image11.CbKpge6z.png",K="/projects/Qtruck/en/latest/assets/image12.CzsIf8_z.png",H="/projects/Qtruck/en/latest/assets/image3.Cr5Zm1xa.png",V="/projects/Qtruck/en/latest/assets/image5.DGjI1nX0.png",W="data:image/png;base64,",T="data:image/png;base64,",M="data:image/png;base64,",N="/projects/Qtruck/en/latest/assets/image9.CuVwrAYz.png",X="/projects/Qtruck/en/latest/assets/image10.BNKdBbH8.png",J="/projects/Qtruck/en/latest/assets/image2.BFKi5nkP.png",Z="data:image/png;base64,",t="data:image/png;base64,",L="data:image/png;base64,",_="/projects/Qtruck/en/latest/assets/image8.CS4aJ2az.png",$="/projects/Qtruck/en/latest/assets/image9.BWKV6lMr.png",tt="data:image/png;base64,",et="data:image/png;base64,",ot="data:image/png;base64,",it="data:image/png;base64,",rt="/projects/Qtruck/en/latest/assets/image14.Dxa7CH83.png",s="data:image/png;base64,",at="data:image/png;base64,",nt="/projects/Qtruck/en/latest/assets/image17.DU5ku9Bz.png",st="/projects/Qtruck/en/latest/assets/image18.Dnl2zkFC.png",lt="/projects/Qtruck/en/latest/assets/image19.Co-ArUsY.png",wt=JSON.parse('{"title":"3. Smart Function Lesson","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3.Smart_Function_Lesson.md","filePath":"docs/3.Smart_Function_Lesson.md"}'),At={name:"docs/3.Smart_Function_Lesson.md"};function ct(gt,o,ht,dt,pt,mt){return c(),g("div",null,[...o[0]||(o[0]=[h('<h1 id="_3-smart-function-lesson" tabindex="-1">3. Smart Function Lesson <a class="header-anchor" href="#_3-smart-function-lesson" aria-label="Permalink to &quot;3. Smart Function Lesson&quot;">​</a></h1><h2 id="_3-1-intelligent-line-following" tabindex="-1">3.1 Intelligent Line Following <a class="header-anchor" href="#_3-1-intelligent-line-following" aria-label="Permalink to &quot;3.1 Intelligent Line Following&quot;">​</a></h2><h3 id="_3-1-1-preparation" tabindex="-1">3.1.1 Preparation <a class="header-anchor" href="#_3-1-1-preparation" aria-label="Permalink to &quot;3.1.1 Preparation&quot;">​</a></h3><p>(1) Connect 4-ch line follower to the port shown on below picture (Port No.4 of expansion board).</p><img loading="lazy" height="729" src="'+d+'" class="common_img" width="500px"><p>(2) Prepare a black line, not too wide.</p><img loading="lazy" height="377" src="'+p+'" class="common_img" width="500px"><h3 id="_3-1-2-learning-objective" tabindex="-1">3.1.2 Learning Objective <a class="header-anchor" href="#_3-1-2-learning-objective" aria-label="Permalink to &quot;3.1.2 Learning Objective&quot;">​</a></h3><p>(1) Learn about the principle of 4-ch line follower and corresponding coding blocks.</p><p>(2) Program Qtruck to move along black line.</p><h3 id="_3-1-3-project-logic" tabindex="-1">3.1.3 Project Logic <a class="header-anchor" href="#_3-1-3-project-logic" aria-label="Permalink to &quot;3.1.3 Project Logic&quot;">​</a></h3><p>Use 4-channel line follower sensor to detect black and white lines, which enable Qtruck move along black line.</p><p>The sensor has four sensing units, and each unit includes an infrared emitter and an infrared receiver. If the infrared light is reflected, for example when it encounters a white or other light-colored surface, the receiver will receive the infrared signal, and you will see the corresponding blue LED indicator light up on the back of the line follower sensor. If the infrared light is absorbed or cannot be reflected, the receiver will not receive any signal.</p><p>If you find that line following does not work properly during use, you can adjust the sensor sensitivity with a screwdriver. Turning clockwise will increase the sensitivity, while turning counterclockwise will decrease it.</p><img loading="lazy" height="699" src="'+m+'" class="common_img" width="500px"><p>Sensitivity Adjustment Location</p><h3 id="_3-1-4-program-writing" tabindex="-1">3.1.4 Program Writing <a class="header-anchor" href="#_3-1-4-program-writing" aria-label="Permalink to &quot;3.1.4 Program Writing&quot;">​</a></h3><ul><li><strong>Extension Package Adding Method</strong></li></ul><p>Online programming: click <a href="https://makecode.microbit.org/" target="_blank" rel="noreferrer">https://makecode.microbit.org/</a> to enter the programming interface. After creating a new project, click <strong>&quot;Extensions&quot;</strong> to add Hiwonder software package for programming.</p><p>Add <a href="https://github.com/Hiwonder/Startbit" target="_blank" rel="noreferrer">https://github.com/Hiwonder/Startbit</a>for micor:bit V1.5.</p><p>Add <a href="https://github.com/Hiwonder/StartbitV2" target="_blank" rel="noreferrer">https://github.com/Hiwonder/StartbitV2</a> for micro:bit V2.0.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Please select the expansion package corresponding to the version of micro:bit. The version of micro:bit can be viewed at the lower right corner of the board.</p></div><ul><li><strong>Block Coding Learning</strong></li></ul><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Coding Block</strong></th><th style="text-align:center;"><strong>Class</strong></th><th style="text-align:center;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="50" width="324" src="'+b+'"></td><td style="text-align:center;"><img loading="lazy" height="41" width="139" src="'+u+'"></td><td style="text-align:center;">Determine sensor status</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="180" width="186" src="'+w+'"></td><td style="text-align:center;"><img loading="lazy" height="31" width="115" src="'+f+'"></td><td style="text-align:center;">If the condition is <code>True</code>, execute statement 1 (requires to add), otherwise, execute statement 2 (requires to add).</td></tr></tbody></table><ul><li><strong>Block Coding Combination</strong></li></ul><img loading="lazy" height="257" width="610" src="'+k+'" class="common_img"><img loading="lazy" height="391" width="905" src="'+x+'" class="common_img"><h3 id="_3-1-5-project-outcome" tabindex="-1">3.1.5 Project Outcome <a class="header-anchor" href="#_3-1-5-project-outcome" aria-label="Permalink to &quot;3.1.5 Project Outcome&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>For sensor sensitivity adjustment, please refer to the video in <a href="./Appendix.html">Appendix-&gt;Robot Debug</a>.</p></div><p>Connect micro:bit board only to your computer. After the program is transferred to micro:bit, insert it into expansion board. After turning on the switch, place the Qtruck robot on the laid-out black line. You will see the Qtruck move along the direction of the black line.</p><h2 id="_3-2-line-following-and-light-up" tabindex="-1">3.2 Line Following and Light up <a class="header-anchor" href="#_3-2-line-following-and-light-up" aria-label="Permalink to &quot;3.2 Line Following and Light up&quot;">​</a></h2><h3 id="_3-2-1-preparation" tabindex="-1">3.2.1 Preparation <a class="header-anchor" href="#_3-2-1-preparation" aria-label="Permalink to &quot;3.2.1 Preparation&quot;">​</a></h3><p>(1) Connect 4-ch line follower to the port shown on below picture (Port 4 of expansion board).</p><img loading="lazy" height="888" src="'+R+'" class="common_img" width="500px"><p>(2) Prepare your black line, not too wide.</p><img loading="lazy" height="376" src="'+I+'" class="common_img" width="500px"><h3 id="_3-2-2-learning-objective" tabindex="-1">3.2.2 Learning Objective <a class="header-anchor" href="#_3-2-2-learning-objective" aria-label="Permalink to &quot;3.2.2 Learning Objective&quot;">​</a></h3><p>(1) Learn about the principle of 4-ch line follower.</p><p>(2) Program Qtruck to move along the black line and change RGB light color.</p><h3 id="_3-2-3-project-logic" tabindex="-1">3.2.3 Project Logic <a class="header-anchor" href="#_3-2-3-project-logic" aria-label="Permalink to &quot;3.2.3 Project Logic&quot;">​</a></h3><p>Use 4-channel line follower sensor to detect black and white lines, which enable Qtruck move along black line.</p><p>The sensor has four sensing units, and each unit includes an infrared emitter and an infrared receiver. If the infrared light is reflected, for example when it encounters a white or other light-colored surface, the receiver will receive the infrared signal, and you will see the corresponding blue LED indicator light up on the back of the line follower sensor. If the infrared light is absorbed or cannot be reflected, the receiver will not receive any signal.</p><p>If you find that line following does not work properly during use, you can adjust the sensor sensitivity with a screwdriver. Turning clockwise will increase the sensitivity, while turning counterclockwise will decrease it.</p><img loading="lazy" height="562" src="'+S+'" class="common_img" width="500px"><p>Sensitivity Adjustment Location</p><h3 id="_3-2-4-program-writing" tabindex="-1">3.2.4 Program Writing <a class="header-anchor" href="#_3-2-4-program-writing" aria-label="Permalink to &quot;3.2.4 Program Writing&quot;">​</a></h3><ul><li><strong>Extension Package Adding Method</strong></li></ul><p>Online programming: click <a href="https://makecode.microbit.org/" target="_blank" rel="noreferrer">https://makecode.microbit.org/</a> to enter the programming interface. After creating a new project, click <strong>&quot;Extensions&quot;</strong> to add Hiwonder software package for programming.</p><p>Add <a href="https://github.com/Hiwonder/Startbit" target="_blank" rel="noreferrer">https://github.com/Hiwonder/Startbit</a> for micor:bit V1.5.</p><p>Add <a href="https://github.com/Hiwonder/StartbitV2" target="_blank" rel="noreferrer">https://github.com/Hiwonder/StartbitV2</a> for micro:bit V2.0.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Please select the expansion package corresponding to the version of micro:bit. The version of micro:bit can be viewed at the lower right corner of the board.</p></div><ul><li><strong>Block Coding Learning</strong></li></ul><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Block Coding</strong></th><th style="text-align:center;"><strong>Class</strong></th><th style="text-align:center;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="71" width="287" src="'+E+'"></td><td style="text-align:center;"><img loading="lazy" height="41" width="139" src="'+i+'"></td><td style="text-align:center;">Set the serial number of light and its color. After setting is complete, use <strong>&quot;show light&quot;</strong> coding block to put the setting into effect.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="70" width="108" src="'+C+'"></td><td style="text-align:center;"><img loading="lazy" height="41" width="139" src="'+i+'"></td><td style="text-align:center;">Use with the above coding block to emit corresponding light color.</td></tr></tbody></table><ul><li><strong>Block Coding Combination</strong></li></ul><img loading="lazy" height="680" width="620" src="'+v+'" class="common_img"><img loading="lazy" height="309" width="718" src="'+y+'" class="common_img"><h3 id="_3-2-5-project-outcome" tabindex="-1">3.2.5 Project Outcome <a class="header-anchor" href="#_3-2-5-project-outcome" aria-label="Permalink to &quot;3.2.5 Project Outcome&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>For sensor sensitivity adjustment, please refer to the video in <a href="./Appendix.html">Appendix-&gt;Robot Debug</a>.</p></div><p>Connect micro:bit board only to your computer. After the program is transferred to micro:bit, insert it into expansion board. Turn on Qtruck, it will move along the black line, then RGB light will regularly change color.</p><h2 id="_3-3-intelligent-voice-control" tabindex="-1">3.3 Intelligent Voice Control <a class="header-anchor" href="#_3-3-intelligent-voice-control" aria-label="Permalink to &quot;3.3 Intelligent Voice Control&quot;">​</a></h2><h3 id="_3-3-1-preparation" tabindex="-1">3.3.1 Preparation <a class="header-anchor" href="#_3-3-1-preparation" aria-label="Permalink to &quot;3.3.1 Preparation&quot;">​</a></h3><p>(1) The location of the sound sensor on the Qtruck robot.</p><img loading="lazy" height="729" src="'+q+'" class="common_img" width="500px"><p>(2) The distribution and placement of the servos on the Qtruck.</p><img loading="lazy" height="800" src="'+e+'" class="common_img" width="700px"><p>(3) Prepare a small block.</p><h3 id="_3-3-2-learning-objective" tabindex="-1">3.3.2 Learning Objective <a class="header-anchor" href="#_3-3-2-learning-objective" aria-label="Permalink to &quot;3.3.2 Learning Objective&quot;">​</a></h3><p>(1) Gain a basic understanding of the sound sensor and servos.</p><p>(2) Learn how to use logic instruction blocks.</p><p>(3) Program the Qtruck robot to grab objects upon hearing a sound.</p><h3 id="_3-3-3-project-logic" tabindex="-1">3.3.3 Project Logic <a class="header-anchor" href="#_3-3-3-project-logic" aria-label="Permalink to &quot;3.3.3 Project Logic&quot;">​</a></h3><p>Qtruck is equipped with a sound sensor that can detect sound volume levels. By programming, we control the three servos on the robotic arm to perform a grabbing action.</p><p>The sound sensor functions similarly to a microphone. It is used to receive sound waves, but it cannot be used to measure noise intensity.</p><p>A servo can precisely control the rotation angle of its horn, which is why it is often used in mechanical systems that require high accuracy. A servo typically consists of a motor, control circuit board, gear set, and potentiometer.</p><h3 id="_3-3-4-program-writing" tabindex="-1">3.3.4 Program Writing <a class="header-anchor" href="#_3-3-4-program-writing" aria-label="Permalink to &quot;3.3.4 Program Writing&quot;">​</a></h3><ul><li><strong>Extension Package Adding Method</strong></li></ul><p>Online programming: click <a href="https://makecode.microbit.org/" target="_blank" rel="noreferrer">https://makecode.microbit.org/</a> to enter the programming interface. After creating a new project, click <strong>&quot;Extensions&quot;</strong> to add Hiwonder software package for programming.</p><p>Add <a href="https://github.com/Hiwonder/Startbit" target="_blank" rel="noreferrer">https://github.com/Hiwonder/Startbit</a> for micor:bit V1.5.</p><p>Add <a href="https://github.com/Hiwonder/StartbitV2" target="_blank" rel="noreferrer">https://github.com/Hiwonder/StartbitV2</a> for micro:bit V2.0.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Please select the expansion package corresponding to the version of micro:bit. The version of micro:bit can be viewed at the lower right corner of the back of the board.</p></div><ul><li><strong>Block Coding Learning</strong></li></ul><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Block Coding</strong></th><th style="text-align:center;"><strong>Class</strong></th><th style="text-align:center;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="41" width="578" src="'+G+'"></td><td style="text-align:center;"><img loading="lazy" height="41" width="139" src="'+r+'"></td><td style="text-align:center;">You can set the rotation angle and range for servos 1 to 8.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="44" width="131" src="'+B+'"></td><td style="text-align:center;"><img loading="lazy" height="41" width="139" src="'+r+'"></td><td style="text-align:center;">Obtain the volume level detected by the sound sensor, ranging from <code>0</code> to <code>255</code>.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="112" width="185" src="'+l+'"></td><td style="text-align:center;"><img loading="lazy" height="39" width="139" src="'+a+'"></td><td style="text-align:center;">If the specified condition is met, the statement will be executed (to be defined by the user).</td></tr></tbody></table><ul><li><strong>Block Coding Combination</strong></li></ul><p>The program is as follow:</p><img loading="lazy" height="396" width="647" src="'+P+'" class="common_img"><img loading="lazy" height="755" width="680" src="'+F+'" class="common_img"><p>The <strong>&quot;Sound volume&quot;</strong> value in the program can be adjusted according to actual conditions.</p><h3 id="_3-3-5-project-outcome" tabindex="-1">3.3.5 Project Outcome <a class="header-anchor" href="#_3-3-5-project-outcome" aria-label="Permalink to &quot;3.3.5 Project Outcome&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>For better results, please operate in a quiet environment. Also, do not use the robotic arm to pick up objects weighing more than 50 grams. If the robotic arm shows abnormal movements or positions after being powered on, please refer to <a href="./Appendix.html">Appendix -&gt; Robot Debug</a> to watch the instructional video.</p></div><p>Insert the micro:bit controller into the computer separately, download the program, and then insert it into the expansion board. After turning on the switch, you can control the robotic arm by clapping your hands. When you clap once, the robotic arm will pick up the block placed in front of it.</p><h2 id="_3-4-grab-in-a-certain-distance" tabindex="-1">3.4 Grab in a Certain Distance <a class="header-anchor" href="#_3-4-grab-in-a-certain-distance" aria-label="Permalink to &quot;3.4 Grab in a Certain Distance&quot;">​</a></h2><h3 id="_3-4-1-preparation" tabindex="-1">3.4.1 Preparation <a class="header-anchor" href="#_3-4-1-preparation" aria-label="Permalink to &quot;3.4.1 Preparation&quot;">​</a></h3><p>(1) Connect ultrasonic sensor to port 2 of expansion board.</p><img loading="lazy" height="1072" src="'+n+'" class="common_img" width="600px"><img loading="lazy" height="411" width="585" src="'+U+'" class="common_img"><p>(2) The position of servos on Qtruck.</p><img loading="lazy" height="800" src="'+e+'" class="common_img" width="500px"><p>(3) Prepare a square block.</p><h3 id="_3-4-2-learning-objective" tabindex="-1">3.4.2 Learning Objective <a class="header-anchor" href="#_3-4-2-learning-objective" aria-label="Permalink to &quot;3.4.2 Learning Objective&quot;">​</a></h3><p>(1) Learn about the principle of ultrasonic sensor.</p><p>(2) Learn about the coding block related to ultrasonic sensor.</p><p>(3) Enable Qtruck to grab object in a certain distance through programming.</p><h3 id="_3-4-3-project-logic" tabindex="-1">3.4.3 Project Logic <a class="header-anchor" href="#_3-4-3-project-logic" aria-label="Permalink to &quot;3.4.3 Project Logic&quot;">​</a></h3><p>The ultrasonic sensor is used to measure distance, and the position of the object in front is determined through programming. If the conditions are met, the robotic arm will proceed to pick up the object.</p><p>The ultrasonic sensor is equipped with two transducers, one for transmitting and one for receiving ultrasonic waves. When measuring distance, the module automatically emits eight 40 kHz square wave pulses to detect whether an echo is returned. If an echo is detected, the sensor outputs a high-level signal. The duration of this high-level signal corresponds to the time it takes for the ultrasonic waves to travel to the object and bounce back.</p><p>Formula: measured distance = (the duration of high level * sound velocity (<code>340M/S</code>)) / <code>2</code></p><h3 id="_3-4-4-program-writing" tabindex="-1">3.4.4 Program Writing <a class="header-anchor" href="#_3-4-4-program-writing" aria-label="Permalink to &quot;3.4.4 Program Writing&quot;">​</a></h3><ul><li><strong>Extension Package Adding Method</strong></li></ul><p>Online programming: click <a href="https://makecode.microbit.org/" target="_blank" rel="noreferrer">https://makecode.microbit.org/</a> to enter the programming interface. After creating a new project, click <strong>&quot;Extensions&quot;</strong> to add Hiwonder software package for programming.</p><p>Add <a href="https://github.com/Hiwonder/Startbit" target="_blank" rel="noreferrer">https://github.com/Hiwonder/Startbit</a> for micor:bit V1.5.</p><p>Add <a href="https://github.com/Hiwonder/StartbitV2" target="_blank" rel="noreferrer">https://github.com/Hiwonder/StartbitV2</a> for micro:bit V2.0.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Please select the expansion package corresponding to the version of micro:bit. The version of micro:bit can be viewed at the lower right corner of the board.</p></div><ul><li><strong>Block Coding Learning</strong></li></ul><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Block Coding</strong></th><th style="text-align:center;"><strong>Class</strong></th><th style="text-align:center;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="63" width="226" src="'+j+'"></td><td style="text-align:center;"><img loading="lazy" height="38" width="171" src="'+O+'"></td><td style="text-align:center;">Create a variable named <code>distance</code> and assign it a value of <code>0</code>.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="57" width="341" src="'+z+'"></td><td style="text-align:center;"><img loading="lazy" height="41" width="139" src="'+Q+'"></td><td style="text-align:center;">Get the distance of the ahead object.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="52" width="174" src="'+D+'"></td><td style="text-align:center;"><img loading="lazy" height="39" width="139" src="'+a+'"></td><td style="text-align:center;">If two inputs are <code>True</code>, the result will be <code>True</code>.</td></tr></tbody></table><ul><li><strong>Block Coding Combination</strong></li></ul><img loading="lazy" height="327" width="477" src="'+Y+'" class="common_img"><img loading="lazy" height="340" width="489" src="'+K+'" class="common_img"><h3 id="_3-4-5-project-outcome" tabindex="-1">3.4.5 Project Outcome <a class="header-anchor" href="#_3-4-5-project-outcome" aria-label="Permalink to &quot;3.4.5 Project Outcome&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Do not use the robotic arm to pick up objects weighing more than 50 grams. Additionally, if the robotic arm shows abnormal movements or positions after being powered on, please refer to <a href="./Appendix.html">Appendix-&gt;Robot Debug</a> to watch the instructional video.</p></div><p>Connect micro:bit board only to your computer. After the program is transferred to micro:bit, turn on Qtruck, then you will see Qtruck keeps still. After putting a block in front of ultrasonic sensor, Qtruck will grab and place it at a side.</p><h2 id="_3-5-obstacle-clearance" tabindex="-1">3.5 Obstacle Clearance <a class="header-anchor" href="#_3-5-obstacle-clearance" aria-label="Permalink to &quot;3.5 Obstacle Clearance&quot;">​</a></h2><h3 id="_3-5-1-preparation" tabindex="-1">3.5.1 Preparation <a class="header-anchor" href="#_3-5-1-preparation" aria-label="Permalink to &quot;3.5.1 Preparation&quot;">​</a></h3><p>(1) Connect ultrasonic sensor to port 2 of expansion board.</p><img loading="lazy" height="1072" src="'+n+'" class="common_img" width="600px"><img loading="lazy" height="413" src="'+H+'" class="common_img" width="500px"><p>(2) The position of servos on Qtruck.</p><img loading="lazy" height="800" src="'+e+'" class="common_img" width="700px"><p>(3) Prepare several blocks.</p><h3 id="_3-5-2-learning-objective" tabindex="-1">3.5.2 Learning Objective <a class="header-anchor" href="#_3-5-2-learning-objective" aria-label="Permalink to &quot;3.5.2 Learning Objective&quot;">​</a></h3><p>(1) Learn about the principle of the feature.</p><p>(2) Understand and be able to use Boolean instruction blocks in the <strong>&quot;Logic&quot;</strong> category.</p><p>(3) Enable Qtruck to automatically determine the ahead object on a specific path and carry it to the corresponding position through programming.</p><h3 id="_3-5-3-project-logic" tabindex="-1">3.5.3 Project Logic <a class="header-anchor" href="#_3-5-3-project-logic" aria-label="Permalink to &quot;3.5.3 Project Logic&quot;">​</a></h3><p>Set Qtruck to go forward and use ultrasonic sensor to detect distance. When the distance is less than a certain value, it is determined that an obstacle is encountered in front of it, and then the obstacle will be picked up and moved out of the way, and then it will continue to move forward.</p><h3 id="_3-5-4-program-writing" tabindex="-1">3.5.4 Program Writing <a class="header-anchor" href="#_3-5-4-program-writing" aria-label="Permalink to &quot;3.5.4 Program Writing&quot;">​</a></h3><ul><li><strong>Extension Package Adding Method</strong></li></ul><p>Online programming: click <a href="https://makecode.microbit.org/" target="_blank" rel="noreferrer">https://makecode.microbit.org/</a> to enter the programming interface. After creating a new project, click <strong>&quot;Extensions&quot;</strong> to add Hiwonder software package for programming.</p><p>Add <a href="https://github.com/Hiwonder/Startbit" target="_blank" rel="noreferrer">https://github.com/Hiwonder/Startbit</a> for micor:bit V1.5.</p><p>Add <a href="https://github.com/Hiwonder/StartbitV2" target="_blank" rel="noreferrer">https://github.com/Hiwonder/StartbitV2</a> for micro:bit V2.0.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Please select the expansion package corresponding to the version of micro:bit. The version of micro:bit can be viewed at the lower right corner of the board.</p></div><ul><li><strong>Block Coding Learning</strong></li></ul><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Block Coding</strong></th><th style="text-align:center;"><strong>Class</strong></th><th style="text-align:center;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="46" width="326" src="'+V+'"></td><td style="text-align:center;"><img loading="lazy" height="41" width="139" src="'+W+'"></td><td style="text-align:center;">Set the speed of <code>motor 1</code> and <code>motor 2</code>. from <code>-100</code> to <code>100</code>, which can control Qtruck to go forward or turn.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="52" width="174" src="'+T+'"></td><td style="text-align:center;"><img loading="lazy" height="39" width="139" src="'+M+'"></td><td style="text-align:center;">If two inputs are <code>True</code>, the result will be <code>True</code>.</td></tr></tbody></table><ul><li><strong>Block Coding Combination</strong></li></ul><img loading="lazy" height="291" width="475" src="'+N+'" class="common_img"><img loading="lazy" height="497" width="629" src="'+X+'" class="common_img"><p><strong>&quot;Distance&quot;</strong> in program can be modified according to actual situation.</p><h3 id="_3-5-5-project-outcome" tabindex="-1">3.5.5 Project Outcome <a class="header-anchor" href="#_3-5-5-project-outcome" aria-label="Permalink to &quot;3.5.5 Project Outcome&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Do not use the robotic arm to pick up objects weighing more than 50 grams. Additionally, if the robotic arm shows abnormal movements or positions after being powered on, please refer to <a href="./Appendix.html">Appendix-&gt;Robot Debug</a> to watch the instructional video.</p></div><p>Connect micro:bit board only to your computer. After the program is transferred to micro:bit, insert it into expansion board. Turn on Qtruck, then it will go forward. When encounter an obstacle, it will clear it out of its way and keep moving.</p><h2 id="_3-6-line-following-and-obstacle-clearance" tabindex="-1">3.6 Line Following and Obstacle Clearance <a class="header-anchor" href="#_3-6-line-following-and-obstacle-clearance" aria-label="Permalink to &quot;3.6 Line Following and Obstacle Clearance&quot;">​</a></h2><h3 id="_3-6-1-preparation" tabindex="-1">3.6.1 Preparation <a class="header-anchor" href="#_3-6-1-preparation" aria-label="Permalink to &quot;3.6.1 Preparation&quot;">​</a></h3><p>(1) The location of the ultrasonic sensor on the Qtruck robot, port 2 of the expansion board.</p><img loading="lazy" height="565" src="'+J+'" class="common_img" width="500px"><p>(2) Distribution of the servo IDs on the robotic arm.</p><img loading="lazy" height="800" src="'+e+'" class="common_img" width="700px"><p>(3) Prepare a black line, not too thin or too wide, and a small block.</p><h3 id="_3-6-2-learning-objective" tabindex="-1">3.6.2 Learning Objective <a class="header-anchor" href="#_3-6-2-learning-objective" aria-label="Permalink to &quot;3.6.2 Learning Objective&quot;">​</a></h3><p>(1) Understand the principle of this feature.</p><p>(2) Program the Qtruck to detect obstacles while line following and transport the detected obstacle to a designated area.</p><h3 id="_3-6-3-project-logic" tabindex="-1">3.6.3 Project Logic <a class="header-anchor" href="#_3-6-3-project-logic" aria-label="Permalink to &quot;3.6.3 Project Logic&quot;">​</a></h3><p>Configure the Qtruck robot to perform line following. While following the line, use the ultrasonic sensor to detect distance. When the detected distance is within the set threshold, it determines that there is an obstacle ahead. At this stage, the robot will pick up and remove the obstacle. After completing this action, it will continue line following.</p><h3 id="_3-6-4-program-writing" tabindex="-1">3.6.4 Program Writing <a class="header-anchor" href="#_3-6-4-program-writing" aria-label="Permalink to &quot;3.6.4 Program Writing&quot;">​</a></h3><ul><li><strong>Extension Package Adding Method</strong></li></ul><p>Online programming: click <a href="https://makecode.microbit.org/" target="_blank" rel="noreferrer">https://makecode.microbit.org/</a> to enter the programming interface. After creating a new project, click <strong>&quot;Extensions&quot;</strong> to add Hiwonder software package for programming.</p><p>Add <a href="https://github.com/Hiwonder/Startbit" target="_blank" rel="noreferrer">https://github.com/Hiwonder/Startbit</a> for micor:bit V1.5.</p><p>Add <a href="https://github.com/Hiwonder/StartbitV2" target="_blank" rel="noreferrer">https://github.com/Hiwonder/StartbitV2</a> for micro:bit V2.0.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Please select the expansion package corresponding to the version of micro:bit. The version of micro:bit can be viewed at the lower right corner of the back of the board.</p></div><ul><li><strong>Block Coding Learning</strong></li></ul><div class="wy-table-responsive"><table border="1" class="docutils"><colgroup><col style="width:20%;"><col style="width:20%;"><col style="width:60%;"></colgroup><thead><tr><th style="text-align:center;"><strong>Block Coding</strong></th><th style="text-align:center;"><strong>Class</strong></th><th style="text-align:center;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="43" width="172" src="'+Z+'"></td><td style="text-align:center;"><img loading="lazy" height="41" width="199" src="'+t+'" style="width:200px;"></td><td style="text-align:center;">Initialize the hardware devices.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="100" width="148" src="'+L+'"></td><td style="text-align:center;"><img loading="lazy" height="41" width="199" src="'+t+'"></td><td style="text-align:center;">When powered on, the contents here will be executed first.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="47" width="446" src="'+_+'"></td><td style="text-align:center;"><img loading="lazy" height="41" width="199" src="'+t+'"></td><td style="text-align:center;">Set the speed of <code>Motor 1</code> and <code>Motor 2</code>, with a range from <code>-100</code> to <code>100</code>, to control the robot&#39;s forward movement and turning. A positive value makes the motor rotate forward, and a negative value makes it rotate backward. When set to <code>0</code>, the motor stops rotating.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="40" width="583" src="'+$+'"></td><td style="text-align:center;"><img loading="lazy" height="41" width="199" src="'+t+'"></td><td style="text-align:center;">Control the rotation range, angle, and running time of the specified servo.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="58" width="191" src="'+tt+'"></td><td style="text-align:center;"><img loading="lazy" height="41" width="199" src="'+t+'"></td><td style="text-align:center;">Turn on specific LEDs on the micro:bit&#39;s LED matrix.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="43" width="164" src="'+et+'"></td><td style="text-align:center;"></td><td style="text-align:center;">Delay block, which makes the program wait for a set time before continuing.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="37" width="64" src="'+ot+'"></td><td style="text-align:center;"><img loading="lazy" height="38" width="139" src="'+it+'"></td><td style="text-align:center;">If both inputs are <code>True</code>, the result will be <code>True</code>.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="267" width="207" src="'+rt+'"></td><td style="text-align:center;"><img loading="lazy" height="33" width="140" src="'+s+'"></td><td style="text-align:center;">Define a custom variable.</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="55" width="314" src="'+at+'"></td><td style="text-align:center;"><img loading="lazy" height="33" width="140" src="'+s+'"></td><td style="text-align:center;">Set the value of a variable.</td></tr></tbody></table></div><ul><li><strong>Block Coding Combination</strong></li></ul><p>The program is as follow:</p><img loading="lazy" height="388" width="654" src="'+nt+'" class="common_img"><img loading="lazy" height="757" width="843" src="'+st+'" class="common_img"><img loading="lazy" height="503" width="842" src="'+lt+'" class="common_img"><h3 id="_3-6-5-project-outcome" tabindex="-1">3.6.5 Project Outcome <a class="header-anchor" href="#_3-6-5-project-outcome" aria-label="Permalink to &quot;3.6.5 Project Outcome&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>If the line-following performance is not optimal, please adjust the sensitivity of the sensors. You can also visit <a href="./Appendix.html">Appendix-&gt;Robot Debug</a> to watch related instruction videos.</p></div><p>Insert the micro:bit controller into the computer separately, download the program, and then insert it into the expansion board. After turning on the switch, you will see the Qtruck robot start line following. When the robot encounters an obstacle during the feature, it will stop, pick up and remove the obstacle, and then continue line following.</p>',177)])])}const ft=A(At,[["render",ct]]);export{wt as __pageData,ft as default};
